// Procesar resultados del monitoreo
const output = $input.first().json.stdout;
let results;

try {
  results = JSON.parse(output);
} catch (e) {
  results = {
    timestamp: new Date().toISOString(),
    files_tested: 0,
    files_with_errors: 1,
    files_successful: 0,
    errors_found: [{ error: 'Error parsing monitor output', details: output }],
    status: 'critical'
  };
}

// Calcular métricas adicionales
const error_rate = results.files_tested > 0 ? 
  (results.files_with_errors / results.files_tested * 100).toFixed(1) : 0;

const health_score = results.files_tested > 0 ? 
  (results.files_successful / results.files_tested * 100).toFixed(1) : 0;

return {
  json: {
    ...results,
    error_rate: parseFloat(error_rate),
    health_score: parseFloat(health_score),
    needs_attention: results.files_with_errors > 0,
    severity: results.status === 'critical' ? 'high' : 
              results.status === 'warning' ? 'medium' : 'low'
  }
};

// Log de errores críticos detectados
const data = $input.first().json;

console.log('🚨 ERRORES DE COMPILACIÓN DETECTADOS:');
console.log(`📊 Archivos testeados: ${data.files_tested}`);
console.log(`❌ Archivos con errores: ${data.files_with_errors}`);
console.log(`✅ Archivos exitosos: ${data.files_successful}`);
console.log(`📈 Tasa de error: ${data.error_rate}%`);
console.log(`🏥 Puntuación de salud: ${data.health_score}%`);
console.log(`⚠️  Severidad: ${data.severity}`);

if (data.errors_found && data.errors_found.length > 0) {
  console.log('\n📋 ERRORES ESPECÍFICOS:');
  data.errors_found.forEach((error, index) => {
    console.log(`${index + 1}. ${error.file}:`);
    console.log(`   Error: ${error.error}`);
    console.log(`   Ruta: ${error.path}`);
  });
}

return {
  json: {
    alert_type: 'compilation_errors',
    message: `🚨 ${data.files_with_errors} archivos con errores de compilación`,
    summary: `${data.error_rate}% de tasa de error (${data.files_with_errors}/${data.files_tested})`,
    severity: data.severity,
    requires_action: true,
    timestamp: data.timestamp,
    details: data.errors_found
  }
};

// Log de sistema saludable
const data = $input.first().json;

console.log('✅ SISTEMA SALUDABLE:');
console.log(`📊 Archivos testeados: ${data.files_tested}`);
console.log(`✅ Todos los archivos compilaron exitosamente`);
console.log(`🏥 Puntuación de salud: ${data.health_score}%`);
console.log(`⏰ Timestamp: ${data.timestamp}`);

return {
  json: {
    alert_type: 'system_healthy',
    message: '✅ Sistema funcionando correctamente',
    summary: `${data.files_tested} archivos testeados sin errores`,
    severity: 'low',
    requires_action: false,
    timestamp: data.timestamp,
    health_score: data.health_score
  }
};

// Log de alerta crítica sin auto-corrección
const data = $input.first().json;

console.log('🔥 ALERTA CRÍTICA - REQUIERE ATENCIÓN MANUAL:');
console.log(`Mensaje: ${data.message}`);
console.log(`Resumen: ${data.summary}`);
console.log(`Severidad: ${data.severity}`);
console.log('📧 Se recomienda revisión manual inmediata');

return {
  json: {
    ...data,
    action_taken: 'manual_review_required',
    escalated: true
  }
};
